package net.civeira.phylax.features.access.tenanttermsofuse.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DocumentVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property document of tenant terms of use ")
  void test_document_v_o_builder() {
    Assertions.assertFalse(DocumentVO.nullValue().getDocument().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(DocumentVO.tryFrom(null).getDocument().isPresent(),
        "With a null value, no present result");
    Assertions.assertThrows(ConstraintException.class,
        () -> DocumentVO.tryFrom(Integer.valueOf(1)));
    Assertions.assertEquals("file_1", DocumentVO.from("file_1").getDocument().orElse(null));
    Assertions.assertEquals("[" + "file_1" + "]", DocumentVO.fromTemporal("file_1").toString());
    Assertions.assertFalse(DocumentVO.from("file_1").isDocumentTemporal());
    Assertions.assertTrue(DocumentVO.fromTemporal("file_1").isDocumentTemporal());
    Assertions.assertEquals("[" + "file_1" + "]", DocumentVO.from("file_1").toString());
    Assertions.assertFalse(DocumentVO.tryFrom("1").isDocumentTemporal());
    Assertions.assertTrue(DocumentVO.tryFrom("temp://1").isDocumentTemporal());
  }
}
